import "core-js/modules/es.array.push.js";
import BaseLogin from "@/views/login/components/BaseLogin.vue";
import cookies from "vue-cookies";
import { clientLogin } from "@/utils/api";
import backgroundManager from "@/mixins/backgroundManager";
export default {
  components: {
    BaseLogin
  },
  mixins: [backgroundManager],
  data() {
    return {
      loginFields: [{
        key: "password",
        label: "密码",
        placeholder: "请输入认证码",
        type: "password",
        icon: "lock",
        show: false
      }]
    };
  },
  computed: {
    ownerName() {
      return this.$store.getters["base/storeUserConfig"].ownerName || "穷拾";
    },
    loginTitle() {
      return `${this.ownerName} の 图床`;
    }
  },
  mounted() {
    // 初始化背景图
    this.initializeBackground("loginBkImg", ".login", false);
  },
  methods: {
    async handleLogin(formData) {
      const {
        password
      } = formData;
      const writtenPass = password === "" ? "unset" : password;
      await clientLogin({
        authCode: password
      }).then(res => {
        if (res.status !== 200) {
          this.$message.error("登录失败，请检查密码是否正确");
          return;
        }
        cookies.set("authCode", writtenPass, "14d");
        this.$router.push("/");
        this.$message.success("登录成功");
      }).catch(err => {
        this.$message.error("登录失败，请检查密码是否正确");
      });
    }
  }
};